import classNames from 'classnames';
import type { CSSProperties, FC, ReactNode, Ref } from 'react';
import React, { useMemo } from 'react';

import type { SmartBlockData_Type } from './../../ricos-schema/next-schema/index.js';
import type { CustomSmartBlockStyle } from './../../ricos-types/theme-types.js';

import { DATA_HOOKS } from '../data-hooks.js';
import type { BlockViewModel, SmartBlockCellRenderData } from '../utils/block-view-model.js';
import { hasBottomCenterCell } from '../utils/cell-position.js';
import { computeSmartBlockWrapperVars } from '../utils/compute-block-css-vars.js';
import { computeSmartBlockCellVars } from '../utils/compute-cell-css-vars.js';
import { useShapeOverlay, useSmartBlockEditorContext } from '../utils/smart-block-context.js';
import accessoryStyles from './cell-accessory-scss.js';
import { CellMarker } from './cell-marker.js';
import { CircleDonut } from './circle-donut.js';
import styles from './smart-block-view-scss.js';

// Variant → SCSS module class. Lives next to the only consumer (this view)
// rather than in `viewer/smart-block.tsx` so `components/` doesn't have to
// reach back into `viewer/` for a constant.
const VARIANT_CLASSES: Record<SmartBlockData_Type, string> = {
  SOLID_BOXES: styles.solidBoxes,
  NUMBERED_BOXES: styles.numberedBoxes,
  STATS: styles.stats,
  BAR_STATS: styles.barStats,
  CIRCLE_STATS: styles.circleStats,
  SOLID_BOXES_ALTERNATING: styles.alternatingBoxes,
  SOLID_JOINED_BOXES: styles.solidJoinedBoxes,
  SIDE_LINE_TEXT: styles.sideLineText,
  TOP_LINE_TEXT: styles.topLineText,
  OUTLINE_BOXES_WITH_TOP_CIRCLE: styles.outlineBoxesWithTopCircle,
  BIG_BULLETS: styles.bigBullets,
  SMALL_BULLETS: styles.smallBullets,
  ARROW_BULLETS: styles.arrowBullets,
  PROCESS_STEPS: styles.processSteps,
  STAR_RATING: styles.starRating,
  QUOTE_BOXES: styles.quoteBoxes,
  TIMELINE: styles.timeline,
  MINIMAL_TIMELINE: styles.minimalTimeline,
  PILLS: styles.pills,
  PYRAMID: styles.pyramid,
  VERTICAL_FUNNEL: styles.verticalFunnel,
  STAIRCASE: styles.staircase,
  CIRCLE: styles.circle,
};

type TriangleVariant = 'PYRAMID' | 'VERTICAL_FUNNEL';

const isTriangleVariant = (type: SmartBlockData_Type): type is TriangleVariant =>
  type === 'PYRAMID' || type === 'VERTICAL_FUNNEL';

type ContentSlotProps = {
  className: string;
  'data-smart-block': true;
  'data-type': SmartBlockData_Type;
  'data-column-size': string;
  'data-orientation'?: string;
  style: CSSProperties;
};

type SmartBlockViewProps = {
  viewModel: BlockViewModel;
  themeSmartBlock: CustomSmartBlockStyle | undefined;

  // The inner element (the one with the variant class + data attrs + CSS vars).
  // Editor wires `<NodeViewContent {...props} />`; viewer wires
  // `<div {...props}><RicosNodeContextProvider>...</...></div>`. The renderer
  // doesn't own this element because PM's `NodeViewContent` must hold the
  // content ref — wrapping it in our own div would break the ref and add a
  // structural layer SCSS selectors don't expect.
  contentSlot: (innerProps: ContentSlotProps) => ReactNode;

  outerRef?: Ref<HTMLDivElement>;
  outerClassName?: string;

  // Editor-only siblings rendered inside the wrapper after the inner element:
  // drop cursor, add-cell bar, drag handle. Viewer omits.
  overlayChildren?: ReactNode;

  // Editor-only hook for the triangle family (PYRAMID, VERTICAL_FUNNEL): open
  // the per-cell shape picker when a narrow-mode slice in the cohesive top
  // stack is clicked. The stack lives outside the per-cell
  // `SmartBlockCellEditorContext`, so the cell-level `onShapeClick` can't reach
  // it — the editor passes a cellId-keyed handler here instead. Viewer omits;
  // slices then render without an overlay.
  onTriangleShapeClick?: (cellId: string, event: React.MouseEvent<HTMLButtonElement>) => void;
};

export const SmartBlockView: FC<SmartBlockViewProps> = ({
  viewModel,
  themeSmartBlock,
  contentSlot,
  outerRef,
  outerClassName,
  overlayChildren,
  onTriangleShapeClick,
}) => {
  const { type, columnSize, orientation, totalCells, blockBorder, cells } = viewModel;

  const wrapperVars = useMemo(
    () => computeSmartBlockWrapperVars(blockBorder, themeSmartBlock, type, totalCells),
    [
      blockBorder.borderColor,
      blockBorder.borderWidth,
      blockBorder.borderRadius,
      themeSmartBlock,
      type,
      totalCells,
    ]
  );

  const variantClass = VARIANT_CLASSES[type] ?? VARIANT_CLASSES.SOLID_BOXES;

  const isCircleWithBottomCell = type === 'CIRCLE' && hasBottomCenterCell(totalCells);
  // Math.ceil so N=1 emits `span 1`, not the invalid `span 0.5`.
  const sideRowCount =
    type === 'CIRCLE'
      ? isCircleWithBottomCell
        ? (totalCells - 1) / 2
        : Math.ceil(totalCells / 2)
      : 0;
  const circleInnerStyle = useMemo<CSSProperties | undefined>(() => {
    if (!isCircleWithBottomCell) {
      return undefined;
    }
    const sideRows = (totalCells - 1) / 2;
    const rowMin = `calc(var(--ricos-internal-sb-circle-size) / ${sideRows})`;
    return {
      gridTemplateRows: `repeat(${sideRows}, minmax(${rowMin}, 1fr)) auto`,
    };
  }, [isCircleWithBottomCell, totalCells]);

  const isShapesMode = useMemo(() => !!cells && cells.some(c => !!c.shape), [cells]);

  const slot = contentSlot({
    className: classNames(styles.smartBlock, variantClass),
    'data-smart-block': true,
    'data-type': type,
    'data-column-size': columnSize,
    ...(orientation ? { 'data-orientation': orientation } : {}),
    style: wrapperVars,
  });

  return (
    <div
      ref={outerRef}
      className={classNames(styles.smartBlockWrapper, outerClassName)}
      data-hook={DATA_HOOKS.SMART_BLOCK}
      style={wrapperVars}
    >
      {/* Triangle family (PYRAMID, VERTICAL_FUNNEL): cohesive visual rendered
          above the cells on narrow widths (the cells themselves collapse to
          chip+label rows via CSS). Rendered here — not portaled from each
          cell's NodeView — because the block already holds every child's attrs
          through the view-model adapter. */}
      {isTriangleVariant(type) && cells && (
        <TriangleMobileStack
          variant={type}
          cells={cells}
          themeSmartBlock={themeSmartBlock}
          onTriangleShapeClick={onTriangleShapeClick}
        />
      )}
      {type === 'STAIRCASE' && cells && (
        <StaircaseMobileStack
          cells={cells}
          isShapesMode={isShapesMode}
          themeSmartBlock={themeSmartBlock}
        />
      )}
      {type === 'CIRCLE' && cells ? (
        <div className={styles.circleInner} style={circleInnerStyle}>
          {slot}
          <CircleDonut
            cells={cells}
            themeAccentColor={themeSmartBlock?.accentColor}
            themeLabelColor={themeSmartBlock?.labelColor}
            isShapesMode={isShapesMode}
            gridRow={`1 / span ${sideRowCount}`}
          />
        </div>
      ) : (
        slot
      )}
      {overlayChildren}
    </div>
  );
};

type TriangleMobileStackProps = {
  variant: TriangleVariant;
  cells: SmartBlockCellRenderData[];
  themeSmartBlock: CustomSmartBlockStyle | undefined;
  onTriangleShapeClick?: (cellId: string, event: React.MouseEvent<HTMLButtonElement>) => void;
};

// `isShapesMode` is true when at least one cell carries a shape — matching the
// cell-view rule so the rest of the cells fall back to the default star instead
// of a numeric chip. Mirrors the editor's parent-derived flag in
// `tiptap/smart-block-cell.tsx`.
function TriangleMobileStack({
  variant,
  cells,
  themeSmartBlock,
  onTriangleShapeClick,
}: TriangleMobileStackProps) {
  const isShapesMode = cells.some(cell => !!cell.shape);
  const stackClass =
    variant === 'PYRAMID' ? styles.pyramidMobileStack : styles.verticalFunnelMobileStack;
  return (
    // Not aria-hidden: when the editor wires onTriangleShapeClick, each slice
    // hosts a focusable shape button. The visual marker (number/icon) inside
    // each slice still duplicates the cell content, but AT users can reach the
    // shape picker via the slice buttons just like sighted users do via hover.
    <div className={stackClass}>
      {cells.map((cell, cellIndex) => (
        <TriangleMobileSlice
          key={cellIndex}
          variant={variant}
          cell={cell}
          cellIndex={cellIndex}
          isShapesMode={isShapesMode}
          themeSmartBlock={themeSmartBlock}
          onTriangleShapeClick={onTriangleShapeClick}
        />
      ))}
    </div>
  );
}

type TriangleMobileSliceProps = {
  variant: TriangleVariant;
  cell: SmartBlockCellRenderData;
  cellIndex: number;
  isShapesMode: boolean;
  themeSmartBlock: CustomSmartBlockStyle | undefined;
  onTriangleShapeClick?: (cellId: string, event: React.MouseEvent<HTMLButtonElement>) => void;
};

function TriangleMobileSlice({
  variant,
  cell,
  cellIndex,
  isShapesMode,
  themeSmartBlock,
  onTriangleShapeClick,
}: TriangleMobileSliceProps) {
  const cellVars = computeSmartBlockCellVars(
    { accentColor: cell.accentColor },
    themeSmartBlock,
    variant,
    cellIndex
  );
  // Editor-supplied; null in the viewer, which paints no overlay.
  const ShapeOverlay = useShapeOverlay();
  const hasShape = !!cell.shape || isShapesMode;
  const cellId = cell.cellId;
  const isPyramid = variant === 'PYRAMID';
  const sliceClass = isPyramid ? styles.pyramidMobileSlice : styles.verticalFunnelMobileSlice;
  const numberClass = isPyramid ? styles.pyramidInnerNumber : styles.verticalFunnelInnerNumber;
  const iconClass = isPyramid ? styles.pyramidInnerIcon : styles.verticalFunnelInnerIcon;
  const overlayPositionClass = isPyramid
    ? styles.pyramidOverlayPosition
    : styles.verticalFunnelOverlayPosition;
  // Same trapezoid-centroid override as the desktop slice (cell-view) — the
  // overlay-position class is hashed in the same module as the rule, so it
  // overrides the cross-module `.accessoryOverlay` base layout.
  const overlay =
    hasShape && onTriangleShapeClick && cellId && ShapeOverlay ? (
      <ShapeOverlay
        overlayClassName={classNames(accessoryStyles.accessoryOverlay, overlayPositionClass)}
        hasShape={hasShape}
        onClick={event => onTriangleShapeClick(cellId, event)}
      />
    ) : null;

  return (
    <div className={classNames(sliceClass, accessoryStyles.accessoryOverlayHost)} style={cellVars}>
      <CellMarker
        shape={cell.shape}
        shapeColor={cell.shapeColor}
        isShapesMode={isShapesMode}
        cellIndex={cellIndex}
        numberClassName={numberClass}
        iconClassName={iconClass}
      />
      {overlay}
    </div>
  );
}

const StaircaseMobileStack: React.FC<{
  cells: SmartBlockCellRenderData[];
  isShapesMode: boolean;
  themeSmartBlock: CustomSmartBlockStyle | undefined;
}> = ({ cells, isShapesMode, themeSmartBlock }) => {
  const onCellShapeClick = useSmartBlockEditorContext()?.onCellShapeClick;

  // The stack is a sibling of the cell-list `slot` (which carries the wrapper
  // vars), so the bar width formula's `--ricos-internal-sb-cols` doesn't reach
  // it via inheritance. Emit it locally instead of polluting the shared wrapper
  // style for every variant. cols === cell count for STAIRCASE.
  const stackVars = { '--ricos-internal-sb-cols': cells.length } as CSSProperties;

  return (
    // Decorative in the viewer (markers duplicate the cell content) → hidden
    // from AT. In the editor each bar hosts a focusable shape button, so the
    // stack must stay reachable.
    <div
      className={styles.staircaseMobileStack}
      style={stackVars}
      aria-hidden={onCellShapeClick ? undefined : true}
    >
      {cells.map((cell, cellIndex) => (
        <StaircaseMobileBar
          key={cell.cellId ?? cellIndex}
          cell={cell}
          cellIndex={cellIndex}
          isShapesMode={isShapesMode}
          themeSmartBlock={themeSmartBlock}
        />
      ))}
    </div>
  );
};

const StaircaseMobileBar: React.FC<{
  cell: SmartBlockCellRenderData;
  cellIndex: number;
  isShapesMode: boolean;
  themeSmartBlock: CustomSmartBlockStyle | undefined;
}> = ({ cell, cellIndex, isShapesMode, themeSmartBlock }) => {
  const onCellShapeClick = useSmartBlockEditorContext()?.onCellShapeClick;
  // Editor-supplied; null in the viewer, which paints no overlay.
  const ShapeOverlay = useShapeOverlay();
  const cellVars = computeSmartBlockCellVars(
    { accentColor: cell.accentColor },
    themeSmartBlock,
    'STAIRCASE',
    cellIndex
  );
  const hasShape = !!cell.shape || isShapesMode;
  const cellId = cell.cellId;
  const overlay =
    hasShape && onCellShapeClick && cellId && ShapeOverlay ? (
      <ShapeOverlay
        overlayClassName={accessoryStyles.accessoryOverlay}
        hasShape={hasShape}
        onClick={event => onCellShapeClick(cellId, event)}
      />
    ) : null;
  return (
    <div
      className={classNames(styles.staircaseMobileBar, accessoryStyles.accessoryOverlayHost)}
      style={cellVars}
    >
      <CellMarker
        shape={cell.shape}
        shapeColor={cell.shapeColor}
        isShapesMode={isShapesMode}
        cellIndex={cellIndex}
        numberClassName={styles.staircaseInnerNumber}
        iconClassName={styles.staircaseInnerIcon}
      />
      {overlay}
    </div>
  );
};
