import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/ricos-context.js';
import { useIsEditorMode } from './../../_shared/use-is-editor-mode.js';

import { getCellNumericValue } from '../utils/cell-numeric-value.js';
import { useSmartBlockCellEditorContext } from '../utils/smart-block-context.js';
import styles from './cell-star-rating-scss.js';
import { Stars } from './stars.js';

const MAX_RATING = 5;

type CellStarRatingProps = {
  label?: string | null;
};

export const CellStarRating: React.FC<CellStarRatingProps> = ({ label }) => {
  const onLabelChange = useSmartBlockCellEditorContext()?.onLabelChange;
  const { t } = useContext(RicosContext);
  const isEditorMode = useIsEditorMode();

  const {
    rawLabel,
    clampedValue: rating,
    hasParsedValue,
  } = getCellNumericValue(label, {
    max: MAX_RATING,
  });

  return (
    <div
      className={styles.cellStarRating}
      role="img"
      aria-valuemin={0}
      aria-valuemax={MAX_RATING}
      aria-valuenow={hasParsedValue ? rating : undefined}
      aria-valuetext={rawLabel || undefined}
    >
      <Stars
        rating={rating}
        className={styles.cellStarRatingStars}
        a11yLabel={t('SmartBlock_StarRating_AriaLabel', { rating })}
      />
      {isEditorMode ? (
        <input
          type="text"
          className={classNames(styles.cellStarRatingValueText, styles.cellStarRatingValueInput)}
          value={rawLabel}
          placeholder={t('SmartBlock_CellStarRating_LabelPlaceholder')}
          size={Math.max(rawLabel.length, 4)}
          onChange={event => onLabelChange?.(event.target.value || null)}
          onMouseDown={event => event.stopPropagation()}
          onClick={event => event.stopPropagation()}
        />
      ) : rawLabel ? (
        <span className={styles.cellStarRatingValueText}>{rawLabel}</span>
      ) : null}
    </div>
  );
};
