import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import { useIsEditorMode } from './../../_shared/use-is-editor-mode.js';

import { getCellNumericValue } from '../utils/cell-numeric-value.js';
import { useSmartBlockCellEditorContext } from '../utils/smart-block-context.js';
import styles from './cell-stat-scss.js';

const CIRCLE_RADIUS = 50;

type CellStatProps = {
  type: 'STATS' | 'BAR_STATS' | 'CIRCLE_STATS';
  label?: string | null;
};

export const CellStat: React.FC<CellStatProps> = ({ type, label }) => {
  const onLabelChange = useSmartBlockCellEditorContext()?.onLabelChange;
  const { t } = useContext(RicosContext);
  const isEditorMode = useIsEditorMode();
  const { rawLabel, clampedValue, hasParsedValue } = getCellNumericValue(label);

  const progressProps = {
    role: 'progressbar',
    'aria-valuemin': 0,
    'aria-valuemax': 100,
    'aria-valuenow': hasParsedValue ? clampedValue : undefined,
    'aria-valuetext': rawLabel || undefined,
  };

  const variantInputClass =
    type === 'BAR_STATS'
      ? styles.cellStatBarValueInput
      : type === 'CIRCLE_STATS'
        ? styles.cellStatCircleValueInput
        : styles.cellStatStatsValueInput;

  const variantTextClass =
    type === 'BAR_STATS'
      ? styles.cellStatBarValueText
      : type === 'CIRCLE_STATS'
        ? styles.cellStatCircleValueText
        : styles.cellStatStatsValueText;

  const labelElement = isEditorMode ? (
    <input
      type="text"
      className={`${styles.cellStatValue} ${styles.cellStatValueInput} ${variantInputClass}`}
      value={rawLabel}
      placeholder={t('SmartBlock_CellStat_LabelPlaceholder')}
      onChange={event => onLabelChange?.(event.target.value || null)}
      onMouseDown={event => event.stopPropagation()}
      onClick={event => event.stopPropagation()}
    />
  ) : rawLabel ? (
    <span className={`${styles.cellStatValue} ${variantTextClass}`}>{rawLabel}</span>
  ) : null;

  if (type === 'STATS') {
    return <div className={styles.cellStatStats}>{labelElement}</div>;
  }

  if (type === 'BAR_STATS') {
    return (
      <div className={styles.cellStatBar}>
        <div className={styles.cellStatBarProgress} {...progressProps}>
          <div className={styles.cellStatBarTrack}>
            <div className={styles.cellStatBarFill} style={{ width: `${clampedValue}%` }} />
          </div>
        </div>
        <div className={styles.cellStatBarValue}>{labelElement}</div>
      </div>
    );
  }

  return (
    <div className={styles.cellStatCircle}>
      <div className={styles.cellStatCircleProgress} {...progressProps}>
        <svg
          className={styles.cellStatCircleSvg}
          viewBox="0 0 120 120"
          aria-hidden
          focusable="false"
        >
          <circle className={styles.cellStatCircleTrack} cx="60" cy="60" r={CIRCLE_RADIUS} />
          <circle
            className={styles.cellStatCircleFill}
            cx="60"
            cy="60"
            r={CIRCLE_RADIUS}
            pathLength={100}
            strokeDasharray="100"
            strokeDashoffset={100 - clampedValue}
          />
        </svg>
        <div className={styles.cellStatCircleValue}>{labelElement}</div>
      </div>
    </div>
  );
};
