import { ToggleButton } from '@wix/design-system';
import { Objects as ShapeIcon } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';

import type { ShapeOverlayProps } from '../utils/smart-block-context.js';
import classes from './shape-overlay-scss.js';

export const ShapeOverlay: React.FC<ShapeOverlayProps> = ({
  overlayClassName,
  hasShape,
  onClick,
}) => {
  const { t } = useContext(RicosContext);
  const label = t(
    hasShape ? 'SmartBlock_ReplaceShapeButton_Tooltip' : 'SmartBlock_InsertShapeButton_Tooltip'
  );

  return (
    <div className={classNames(classes.shapeOverlay, overlayClassName)}>
      <ToggleButton
        size="tiny"
        shape="round"
        onClick={onClick}
        labelValue={label}
        tooltipProps={{ enterDelay: 300 }}
        selected
      >
        <ShapeIcon />
      </ToggleButton>
    </div>
  );
};
