import classNames from 'classnames';
import React from 'react';

import type { Media } from './../../ricos-schema/next-schema/index.js';
import { ShapeViewRenderer } from './../../_shared/shape-view-renderer.js';
import { DEFAULT_COLOR } from './../../_shared/shape-view-renderer/consts.js';

import { resolveShapeSrc } from '../utils/resolve-shape-src.js';
import accessoryStyles from './cell-accessory-scss.js';

type CellMarkerProps = {
  shape: Media | undefined;
  shapeColor: string | undefined;
  isShapesMode: boolean;
  cellIndex: number;
  // Override classes composed onto the inner number / icon. Lets a consumer
  // tweak sizing from its own SCSS module without writing cross-file
  // descendant rules.
  numberClassName?: string;
  iconClassName?: string;
};

export const CellMarker: React.FC<CellMarkerProps> = ({
  shape,
  shapeColor,
  isShapesMode,
  cellIndex,
  numberClassName,
  iconClassName,
}) => {
  const hasShape = !!shape || isShapesMode;
  const shapeSrc = hasShape ? resolveShapeSrc(shape) : undefined;
  if (shapeSrc) {
    const shapeColors: Record<string, string> = shapeColor ? { [DEFAULT_COLOR]: shapeColor } : {};
    return (
      <div className={classNames(accessoryStyles.accessoryIcon, iconClassName)}>
        <ShapeViewRenderer
          shapeSrc={shapeSrc}
          colors={shapeColors}
          hideLoadingOverlay
          preserveAspectRatio="xMidYMid meet"
          style={{ width: '100%', height: '100%' }}
        />
      </div>
    );
  }
  return (
    <span className={classNames(accessoryStyles.accessoryNumber, numberClassName)}>
      {cellIndex + 1}
    </span>
  );
};
