import type { MediaItem } from '@wix/ambassador-media-public-media-v1-media-item/types';
import React, { useContext } from 'react';

import { EditorContext, ModalServiceContext } from './../../ricos-context/index.js';
import type { FileSource } from './../../ricos-schema/next-schema/index.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import { ICONS_CATEGORY_ID, SHAPES_CATEGORY_ID } from './../../_shared/shape-select-modal/consts.js';
import { ShapeSelectModal } from './../../_shared/shape-select-modal/shape-select-modal.js';

import { DATA_HOOKS } from '../data-hooks.js';

type Props = { cellId: string } | { blockMode: true };

export const SmartBlockShapePickerModal: React.FC<Props> = props => {
  const { adapter } = useContext(EditorContext);
  const modalService = useContext(ModalServiceContext) || {};

  const closeModal = () => modalService.closeModal(DATA_HOOKS.CELL_SHAPE_PICKER);

  const onShapeSelect = (shape: MediaItem) => {
    const shapeData = shape.assets?.vector?.image;

    if (!shapeData) {
      logInvariant(new Error('Shape data not found'));
      return;
    }

    closeModal();

    const src: FileSource = shapeData.id ? { id: shapeData.id } : { url: shapeData.url };

    if ('cellId' in props) {
      adapter.tiptapEditor.commands.updateNodeAttrsById(props.cellId, { shape: { src } });
      adapter.tiptapEditor
        .chain()
        .selectSmartBlockCell(props.cellId)
        .focus(undefined, { scrollIntoView: false })
        .run();
    } else {
      adapter.tiptapEditor.commands.applyShapeToAllCells({ src });
    }
  };

  return (
    <ShapeSelectModal
      onShapeSelect={onShapeSelect}
      onClose={closeModal}
      allowedCategoryIds={[SHAPES_CATEGORY_ID, ICONS_CATEGORY_ID]}
    />
  );
};
