import React from 'react';

import { unreachable } from './../../_shared/uncreachable.js';

import styles from './stars-scss.js';

type StarsProps = {
  rating: number;
  dataHook?: string;
  a11yLabel?: string;
  className?: string;
};

export const Stars: React.FC<StarsProps> = ({ rating, a11yLabel, className = '', dataHook }) => {
  const normalizedRating = Math.min(Math.max(rating, 0), 5);
  return (
    <div
      className={[styles.root, className].join(' ')}
      data-hook={dataHook}
      data-value={normalizedRating}
    >
      {a11yLabel && <span className={styles.a11yLabel}>{a11yLabel}</span>}
      <div aria-hidden="true" className={styles.innerContainer}>
        {[1, 2, 3, 4, 5].map(index => {
          const iconState = toStarState(normalizedRating, index);
          switch (iconState) {
            case 'full':
              return <StarIcon key={index} className={styles.full} />;
            case 'empty':
              return <StarIcon key={index} className={styles.empty} />;
            case 'half':
              return (
                <div className={styles.halfStarWrapper} key={index}>
                  <StarIcon
                    key="start"
                    className={[styles.halfStarInnerWrapperStart, styles.full].join(' ')}
                  />
                  <StarIcon
                    key="end"
                    className={[styles.halfStarInnerWrapperEnd, styles.empty].join(' ')}
                  />
                </div>
              );
            default:
              throw unreachable(iconState);
          }
        })}
      </div>
    </div>
  );
};

/* index is 1 to 5, like rating */
function toStarState(rating: number, index: number): 'full' | 'half' | 'empty' {
  if (index <= rating) {
    return 'full';
  }
  if (index - rating < 1) {
    const partial = index - rating;
    return partial < 0.25 ? 'full' : partial > 0.75 ? 'empty' : 'half';
  }
  return 'empty';
}

