import React from 'react';

import styles from './cell-quote-glyph-scss.js';

type CellQuoteGlyphProps = {
  position: 'open' | 'close';
};

// Two filled comma shapes that read as a double-quote mark. The raw path is
// the 9-shape (bulb at top, tail dropping down) — the typographic closing-quote
// form. The close variant renders it as-is at bottom-right; the open variant
// rotates 180° to the 6-shape (bulb at bottom, tail curling up) for top-left.
const OPEN_PATH =
  'M3 1c-1.4 0-2.5 1.1-2.5 2.5v4c0 1.4 1.1 2.5 2.5 2.5h.5v1.2c0 1.2-.7 2.2-1.7 2.5l-.3.1v1.7l.5-.1c2.2-.4 3.8-2.3 3.8-4.5V3.5C5.8 2.1 4.4 1 3 1zm7 0C8.6 1 7.5 2.1 7.5 3.5v4c0 1.4 1.1 2.5 2.5 2.5h.5v1.2c0 1.2-.7 2.2-1.7 2.5l-.3.1v1.7l.5-.1c2.2-.4 3.8-2.3 3.8-4.5V3.5C12.8 2.1 11.4 1 10 1z';

export const CellQuoteGlyph: React.FC<CellQuoteGlyphProps> = ({ position }) => {
  const transform = position === 'open' ? 'scale(-1 -1) translate(-14 -16)' : undefined;
  return (
    <span
      className={`${styles.quoteGlyph} ${
        position === 'open' ? styles.quoteOpen : styles.quoteClose
      }`}
      aria-hidden="true"
    >
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 14 16">
        <path d={OPEN_PATH} transform={transform} />
      </svg>
    </span>
  );
};
