import classNames from 'classnames';
import type { CSSProperties } from 'react';
import React from 'react';

import { ShapeViewRenderer } from './../../_shared/shape-view-renderer.js';
import { DEFAULT_COLOR } from './../../_shared/shape-view-renderer/consts.js';
import { resolveDocumentColorToCss } from './../../_shared/theme-color-token.js';

import {
  CIRCLE_BOX_SIZE,
  CIRCLE_CORNER_RADIUS,
  CIRCLE_INNER_RADIUS,
  CIRCLE_OUTER_RADIUS,
  CIRCLE_SEGMENT_GAP,
} from '../consts.js';
import type { SmartBlockCellRenderData } from '../utils/block-view-model.js';
import { getCellMidAngleDeg } from '../utils/cell-position.js';
import { resolveShapeSrc } from '../utils/resolve-shape-src.js';
import { useShapeOverlay, useSmartBlockEditorContext } from '../utils/smart-block-context.js';
import styles from './circle-donut-scss.js';

const CENTER = CIRCLE_BOX_SIZE / 2;
const MID_RADIUS = (CIRCLE_OUTER_RADIUS + CIRCLE_INNER_RADIUS) / 2;
const FALLBACK_FILL = '#E7F0FF';

type CircleDonutProps = {
  cells: SmartBlockCellRenderData[];
  themeAccentColor?: string;
  themeLabelColor?: string | null;
  isShapesMode: boolean;
  gridRow?: string;
};

// Memoized: parent SmartBlockView re-renders on every editor state change
// (selected/focusWithin), but the donut only depends on cells + theme colors +
// the indicator click handler. Skipping the SVG path math on unrelated parent
// re-renders keeps the editor snappy with N=12 cells.
export const CircleDonut = React.memo<CircleDonutProps>(
  ({ cells, themeAccentColor, themeLabelColor, isShapesMode, gridRow }) => {
    const onIndicatorClick = useSmartBlockEditorContext()?.onCellShapeClick;
    // Editor-supplied; null in the viewer, which paints no overlay.
    const ShapeOverlay = useShapeOverlay();

    const total = cells.length;
    if (total === 0) {
      return null;
    }

    // Run through resolveDocumentColorToCss so palette tokens (e.g. `$theme-color-3`)
    // become `var(--ricos-theme-color-3)` — required for the SVG `fill` attribute
    // to follow live palette changes. Hex/rgb values pass through unchanged.
    const resolveFill = (cell: SmartBlockCellRenderData): string => {
      const raw = cell.accentColor ?? themeAccentColor ?? FALLBACK_FILL;
      return resolveDocumentColorToCss(raw) ?? raw;
    };

    return (
      <div
        className={styles.circleDonut}
        data-circle-donut="true"
        aria-hidden="true"
        style={gridRow ? { gridRow } : undefined}
      >
        <svg
          className={styles.svg}
          viewBox={`0 0 ${CIRCLE_BOX_SIZE} ${CIRCLE_BOX_SIZE}`}
          preserveAspectRatio="xMidYMid meet"
          xmlns="http://www.w3.org/2000/svg"
        >
          {total === 1 ? (
            <path d={buildFullRingPath()} fill={resolveFill(cells[0])} fillRule="evenodd" />
          ) : (
            cells.map((cell, i) => {
              const { start, end } = getSegmentAngles(i, total);
              return <path key={i} d={buildSectorPath(start, end)} fill={resolveFill(cell)} />;
            })
          )}
        </svg>
        {cells.map((cell, i) => {
          const { mid } = getSegmentAngles(i, total);
          const { x, y } = polar(MID_RADIUS, mid);
          const hasShape = !!cell.shape || isShapesMode;
          const shapeSrc = hasShape ? resolveShapeSrc(cell.shape ?? undefined) : undefined;
          const resolvedShapeColor = cell.shapeColor ?? themeLabelColor ?? null;
          const shapeColors: Record<string, string> = resolvedShapeColor
            ? { [DEFAULT_COLOR]: resolvedShapeColor }
            : {};
          const style: CSSProperties = {
            left: `${(x / CIRCLE_BOX_SIZE) * 100}%`,
            top: `${(y / CIRCLE_BOX_SIZE) * 100}%`,
          };
          const interactive = Boolean(onIndicatorClick && cell.cellId && hasShape);
          return (
            <div
              key={i}
              className={classNames(styles.indicator, interactive && styles.indicatorInteractive)}
              style={style}
            >
              {shapeSrc ? (
                <div className={styles.indicatorShape}>
                  <ShapeViewRenderer
                    shapeSrc={shapeSrc}
                    colors={shapeColors}
                    hideLoadingOverlay
                    preserveAspectRatio="xMidYMid meet"
                    style={{ width: '100%', height: '100%' }}
                  />
                </div>
              ) : (
                <span className={styles.indicatorNumber}>{i + 1}</span>
              )}
              {interactive && ShapeOverlay && (
                <ShapeOverlay
                  overlayClassName={styles.cellLabelAddOverlay}
                  hasShape={hasShape}
                  onClick={event => onIndicatorClick!(cell.cellId!, event)}
                />
              )}
            </div>
          );
        })}
      </div>
    );
  }
);

CircleDonut.displayName = 'CircleDonut';

// Polar coords measured clockwise from TOP, then mapped to SVG (y-down).
const polar = (radius: number, angleDeg: number): { x: number; y: number } => {
  const angleRad = (angleDeg * Math.PI) / 180;
  return {
    x: CENTER + radius * Math.sin(angleRad),
    y: CENTER - radius * Math.cos(angleRad),
  };
};

// Natural angular bounds for cell `i` (no gap subtraction — the gap is applied
// as a perpendicular offset inside `buildSectorPath`, not by trimming angles).
// Midpoint comes from the shared `getCellMidAngleDeg` so segment positions
// stay locked to label positions.
const getSegmentAngles = (
  index: number,
  total: number
): { start: number; end: number; mid: number } => {
  const span = 360 / total;
  const mid = getCellMidAngleDeg(index, total);
  return {
    start: mid - span / 2,
    end: mid + span / 2,
    mid,
  };
};

const DEG_TO_RAD = Math.PI / 180;
const cosDeg = (deg: number): number => Math.cos(deg * DEG_TO_RAD);
const sinDeg = (deg: number): number => Math.sin(deg * DEG_TO_RAD);

// Filled annular sector with a constant-pixel-width gap between adjacent
// slices. The side edges are lines parallel to the natural radial direction
// at the slice's boundary angle, offset perpendicularly by `halfGap` from
// the center — so the gap between two slices is the same width at the outer
// rim and at the inner rim. Each corner is rounded by an arc of radius
// `cornerR` tangent to both the curved arc (outer or inner) and the
// straight side edge.
const buildSectorPath = (start: number, end: number): string => {
  const outerR = CIRCLE_OUTER_RADIUS;
  const innerR = CIRCLE_INNER_RADIUS;
  const cornerR = CIRCLE_CORNER_RADIUS;
  const halfGap = CIRCLE_SEGMENT_GAP / 2;

  const oRadial = outerR - cornerR;
  const iRadial = innerR + cornerR;

  // Angular inset where the corner-arc CENTER sits, measured from the natural
  // boundary angle. The corner center is at perpendicular distance
  // `halfGap + cornerR` from the natural radial (= halfGap into the gap, plus
  // cornerR more into the slice interior).
  const outerGamma = (Math.asin((halfGap + cornerR) / oRadial) * 180) / Math.PI;
  const innerGamma = (Math.asin((halfGap + cornerR) / iRadial) * 180) / Math.PI;

  // Unit perpendiculars at start/end angles, pointing AWAY from slice interior.
  // At the end boundary the slice interior is on the lower-θ side, so away-from-
  // interior is +(cos θ, sin θ). At the start boundary it's the opposite sign.
  const awayEndX = cosDeg(end);
  const awayEndY = sinDeg(end);
  const awayStartX = -cosDeg(start);
  const awayStartY = -sinDeg(start);

  // Outer and inner arc endpoints (tangent points of the corner arcs with the
  // outer/inner arcs).
  const A = polar(outerR, start + outerGamma); // outer arc start
  const B = polar(outerR, end - outerGamma); // outer arc end
  const E = polar(innerR, end - innerGamma); // inner arc end
  const F = polar(innerR, start + innerGamma); // inner arc start

  // Side-edge tangent points: each corner-arc center shifted by cornerR away
  // from the slice interior puts us exactly on the boundary line (which sits
  // halfway through the gap, halfGap from center).
  const ccCo = polar(oRadial, end - outerGamma); // corner center: end-outer
  const ccCi = polar(iRadial, end - innerGamma); // corner center: end-inner
  const ccGi = polar(iRadial, start + innerGamma); // corner center: start-inner
  const ccHo = polar(oRadial, start + outerGamma); // corner center: start-outer

  const C = { x: ccCo.x + cornerR * awayEndX, y: ccCo.y + cornerR * awayEndY };
  const D = { x: ccCi.x + cornerR * awayEndX, y: ccCi.y + cornerR * awayEndY };
  const G = { x: ccGi.x + cornerR * awayStartX, y: ccGi.y + cornerR * awayStartY };
  const H = { x: ccHo.x + cornerR * awayStartX, y: ccHo.y + cornerR * awayStartY };

  const outerSpan = end - start - 2 * outerGamma;
  const innerSpan = end - start - 2 * innerGamma;
  const largeOuter = outerSpan > 180 ? 1 : 0;
  const largeInner = innerSpan > 180 ? 1 : 0;

  return (
    `M ${A.x} ${A.y} ` +
    `A ${outerR} ${outerR} 0 ${largeOuter} 1 ${B.x} ${B.y} ` +
    `A ${cornerR} ${cornerR} 0 0 1 ${C.x} ${C.y} ` +
    `L ${D.x} ${D.y} ` +
    `A ${cornerR} ${cornerR} 0 0 1 ${E.x} ${E.y} ` +
    `A ${innerR} ${innerR} 0 ${largeInner} 0 ${F.x} ${F.y} ` +
    `A ${cornerR} ${cornerR} 0 0 1 ${G.x} ${G.y} ` +
    `L ${H.x} ${H.y} ` +
    `A ${cornerR} ${cornerR} 0 0 1 ${A.x} ${A.y} ` +
    `Z`
  );
};

// Full ring: outer circle + inner circle as a single path with even-odd fill.
const buildFullRingPath = (): string => {
  const outerR = CIRCLE_OUTER_RADIUS;
  const innerR = CIRCLE_INNER_RADIUS;
  return (
    `M ${CENTER - outerR} ${CENTER} ` +
    `a ${outerR} ${outerR} 0 1 0 ${2 * outerR} 0 ` +
    `a ${outerR} ${outerR} 0 1 0 ${-2 * outerR} 0 ` +
    `M ${CENTER - innerR} ${CENTER} ` +
    `a ${innerR} ${innerR} 0 1 0 ${2 * innerR} 0 ` +
    `a ${innerR} ${innerR} 0 1 0 ${-2 * innerR} 0 ` +
    `Z`
  );
};
