import { ChevronRight } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import type { CSSProperties, FC, ReactNode, Ref } from 'react';
import React, { useMemo } from 'react';

import { HEADER_NAMES } from './../../ricos-common-plugins/title/header-names.js';
import type { CustomSmartBlockStyle } from './../../ricos-types/theme-types.js';
import { ShapeViewRenderer } from './../../_shared/shape-view-renderer.js';
import { DEFAULT_COLOR } from './../../_shared/shape-view-renderer/consts.js';

import { DATA_HOOKS } from '../data-hooks.js';
import { getCellPositionDataAttrs, getCircleCellStyle } from '../utils/cell-position.js';
import type { CellViewModel } from '../utils/cell-view-model.js';
import { computeSmartBlockCellVars } from '../utils/compute-cell-css-vars.js';
import { resolveShapeSrc } from '../utils/resolve-shape-src.js';
import { useShapeOverlay, useSmartBlockCellEditorContext } from '../utils/smart-block-context.js';
import { isBulletVariant } from '../utils/variant-features.js';
import accessoryStyles from './cell-accessory-scss.js';
import { CellMarker } from './cell-marker.js';
import { CellQuoteGlyph } from './cell-quote-glyph.js';
import { CellStarRating } from './cell-star-rating.js';
import { CellStat } from './cell-stat.js';
import styles from './smart-block-view-scss.js';

type ContentSlotProps = {
  className: string;
  style?: CSSProperties;
  'data-heading-level'?: string;
  // Stable marker on the real cell content (editor + viewer markup). On paste,
  // transformPastedHTML keeps only this subtree so the decorative accessories
  // (numbers, shapes, stat labels) don't leak in as stray paragraphs.
  'data-smart-block-content'?: string;
};

type SmartBlockCellViewProps = {
  viewModel: CellViewModel;
  themeSmartBlock: CustomSmartBlockStyle | undefined;

  // Editable region. The renderer computes the content-element props (class /
  // inline style / data-heading-level) and passes them to this function so the
  // caller decides which element owns them. Editor wires a `<NodeViewContent>`
  // (which holds the PM content ref); viewer wires a plain `<div>` wrapping
  // `<RicosNodesRenderer>`. We don't render an extra wrapper div here — that
  // would break PM's `nodeViewContentRef` and add a structural layer that SCSS
  // selectors (`.smartBlockCellContent > p`) don't expect.
  contentSlot: (contentProps: ContentSlotProps) => ReactNode;

  // Editor-only opt-in props. The viewer never passes these.
  outerRef?: Ref<HTMLDivElement>;
  outerClassName?: string;

  // For SOLID_JOINED_BOXES the editor needs per-cell corner data-attrs because
  // `.editorWrapper [data-type="SOLID_JOINED_BOXES"]` overrides
  // `overflow: hidden` → `overflow: visible` (so drag handles + add-cell button
  // aren't clipped). With the wrapper clip gone, corner cells must round
  // themselves via `[data-corner-*]` (see tiptap/smart-block-editor.scss:9-44).
  // The viewer keeps `overflow: hidden` on the wrapper, so its cells need no
  // per-cell flags — it omits this prop.
  extraAttrs?: Record<string, string | number | true | undefined>;

  // Drag handle, etc. Rendered inside the cell after the content slot.
  overlayChildren?: ReactNode;
};

export const SmartBlockCellView: FC<SmartBlockCellViewProps> = ({
  viewModel,
  themeSmartBlock,
  contentSlot,
  outerRef,
  outerClassName,
  extraAttrs,
  overlayChildren,
}) => {
  const {
    type,
    cellIndex,
    totalCells,
    columnSize,
    orientation,
    cellId,
    cellColors,
    shape,
    shapeColor,
    label,
    contentStyle,
    isShapesMode,
  } = viewModel;

  const cellDesignVars = useMemo(
    () => computeSmartBlockCellVars(cellColors, themeSmartBlock, type, cellIndex, orientation),
    [
      cellColors.accentColor,
      cellColors.backgroundColor,
      cellColors.borderColor,
      cellColors.borderWidth,
      cellColors.borderRadius,
      themeSmartBlock,
      type,
      cellIndex,
      orientation,
    ]
  );

  const cellPositionAttrs = useMemo(
    () => getCellPositionDataAttrs(cellIndex, totalCells, columnSize),
    [cellIndex, totalCells, columnSize]
  );

  // CIRCLE variant: each cell gets its column-side + row-position derived from
  // its segment's mid-angle on the donut. The vars (--ricos-internal-sb-row, etc.)
  // are merged into the cell's style; the data-circle-side attr is spread onto
  // the wrapper. Both viewer and editor use the same derivation so cells stay
  // in lock-step with the donut segments rendered by `CircleDonut`.
  const circleStyle = useMemo(
    () => (type === 'CIRCLE' ? getCircleCellStyle(cellIndex, totalCells) : null),
    [type, cellIndex, totalCells]
  );

  // Accessory marker / overlay locals. Variants that don't render a marker
  // (SOLID_BOXES, SIDE_LINE_TEXT, …) just ignore them. The context hook must
  // always run, so we compute these unconditionally rather than gating on
  // variant.
  const onShapeClick = useSmartBlockCellEditorContext()?.onShapeClick;
  // Editor-supplied; null in the viewer, which paints no overlay.
  const ShapeOverlay = useShapeOverlay();
  const hasShape = !!shape || isShapesMode;
  const shapeSrc = hasShape ? resolveShapeSrc(shape) : undefined;
  const shapeColors: Record<string, string> = shapeColor ? { [DEFAULT_COLOR]: shapeColor } : {};

  const shapeContent = shapeSrc ? (
    <ShapeViewRenderer
      shapeSrc={shapeSrc}
      colors={shapeColors}
      hideLoadingOverlay
      preserveAspectRatio="xMidYMid meet"
      style={{ width: '100%', height: '100%' }}
    />
  ) : null;

  const overlay =
    hasShape && onShapeClick && ShapeOverlay ? (
      <ShapeOverlay
        overlayClassName={accessoryStyles.accessoryOverlay}
        hasShape={hasShape}
        onClick={onShapeClick}
      />
    ) : null;

  // Marker shared by variants whose inner block is a 30px flex container
  // (NUMBERED_BOXES, OUTLINE_BOXES_WITH_TOP_CIRCLE, PILLS, BIG_BULLETS).
  const defaultMarker = (
    <CellMarker
      shape={shape}
      shapeColor={shapeColor}
      isShapesMode={isShapesMode}
      cellIndex={cellIndex}
    />
  );

  // Accessories render directly as cell children — no editor-only wrapper
  // around them. PM doesn't try to edit accessories because they sit outside
  // the `NodeViewContent` content slot. Wrapping them would break the
  // `.smartBlockCell > :first-child` selector below, which positions the
  // TIMELINE / MINIMAL_TIMELINE chip absolutely over the connector line.
  const mergedStyle: CSSProperties = circleStyle
    ? { ...cellDesignVars, ...circleStyle.style }
    : cellDesignVars;

  return (
    <div
      ref={outerRef}
      className={classNames(styles.smartBlockCell, outerClassName, {
        [styles.bulletCell]: isBulletVariant(type),
      })}
      data-hook={DATA_HOOKS.SMART_BLOCK_CELL}
      data-smart-block-cell={cellId ?? true}
      style={mergedStyle}
      {...cellPositionAttrs}
      {...(circleStyle ? { 'data-circle-side': circleStyle.side } : {})}
      {...extraAttrs}
    >
      {(() => {
        switch (type) {
          case 'NUMBERED_BOXES': {
            return (
              <div className={accessoryStyles.numberedBand}>
                <div className={accessoryStyles.accessoryFrame}>
                  {defaultMarker}
                  {overlay}
                </div>
              </div>
            );
          }
          case 'OUTLINE_BOXES_WITH_TOP_CIRCLE': {
            return (
              <div className={accessoryStyles.circleRail}>
                <div className={accessoryStyles.circleSlot}>
                  <div className={accessoryStyles.accessoryFrame}>{defaultMarker}</div>
                  {overlay}
                </div>
              </div>
            );
          }
          case 'PROCESS_STEPS': {
            return (
              <div className={accessoryStyles.processRow}>
                <div style={{ position: 'relative' }}>
                  {shapeContent ? (
                    <div className={accessoryStyles.processIcon}>
                      <div style={{ width: 24, height: 24 }}>{shapeContent}</div>
                    </div>
                  ) : (
                    <span className={accessoryStyles.processNumber}>
                      {String(cellIndex + 1).padStart(2, '0')}
                    </span>
                  )}
                  {overlay}
                </div>
                <div className={accessoryStyles.processLine} />
              </div>
            );
          }
          case 'TIMELINE': {
            return (
              <div className={accessoryStyles.timelineChip}>
                {shapeContent ? (
                  <div className={accessoryStyles.timelineIcon}>{shapeContent}</div>
                ) : (
                  <span className={accessoryStyles.timelineNumber}>{cellIndex + 1}</span>
                )}
                {overlay}
              </div>
            );
          }
          case 'MINIMAL_TIMELINE': {
            return <div className={accessoryStyles.minimalTimelineDot} />;
          }
          case 'PILLS': {
            return (
              <div
                className={
                  orientation === 'VERTICAL'
                    ? accessoryStyles.pillVertical
                    : classNames(accessoryStyles.pill, accessoryStyles.numberedBand)
                }
              >
                <div className={accessoryStyles.accessoryFrame}>{defaultMarker}</div>
                {overlay}
              </div>
            );
          }
          case 'BIG_BULLETS': {
            return (
              <div className={accessoryStyles.bulletInline}>
                <div className={accessoryStyles.bulletFrame}>
                  {defaultMarker}
                  {overlay}
                </div>
              </div>
            );
          }
          case 'ARROW_BULLETS': {
            return (
              <div className={accessoryStyles.bulletInline}>
                <div className={accessoryStyles.bulletFrame}>
                  {shapeContent ? (
                    <div className={accessoryStyles.accessoryIcon}>{shapeContent}</div>
                  ) : (
                    <ChevronRight className={accessoryStyles.bulletArrow} />
                  )}
                  {overlay}
                </div>
              </div>
            );
          }
          case 'STATS':
          case 'BAR_STATS':
          case 'CIRCLE_STATS': {
            return <CellStat type={type} label={label} />;
          }
          case 'STAR_RATING': {
            return <CellStarRating label={label} />;
          }
          case 'QUOTE_BOXES': {
            return (
              <>
                <CellQuoteGlyph position="open" />
                <CellQuoteGlyph position="close" />
              </>
            );
          }
          case 'PYRAMID':
          case 'VERTICAL_FUNNEL': {
            // Triangle family — PYRAMID (apex up) and VERTICAL_FUNNEL (apex
            // down) share the same DOM structure but use different SCSS
            // classes for the slice clip-path and centroid math.
            //
            // Variant-specific overlay: layers `<variant>OverlayPosition` (from
            // smart-block-view.scss) onto the base overlay class so the hover
            // shape-picker button anchors to the trapezoid centroid that the
            // marker uses — see `.pyramidSlice` / `.verticalFunnelSlice` in
            // smart-block-view.scss. A cross-file
            // `.pyramidSlice .accessoryOverlay` rule wouldn't match because
            // the two classes are hashed by different modules; composing on
            // the JSX side keeps both classes in the same DOM element so a
            // single-module selector can position the overlay.
            const isPyramid = type === 'PYRAMID';
            const sliceClass = isPyramid ? styles.pyramidSlice : styles.verticalFunnelSlice;
            const innerNumberClass = isPyramid
              ? styles.pyramidInnerNumber
              : styles.verticalFunnelInnerNumber;
            const innerIconClass = isPyramid
              ? styles.pyramidInnerIcon
              : styles.verticalFunnelInnerIcon;
            const overlayPositionClass = isPyramid
              ? styles.pyramidOverlayPosition
              : styles.verticalFunnelOverlayPosition;
            const sliceOverlay =
              hasShape && onShapeClick && ShapeOverlay ? (
                <ShapeOverlay
                  overlayClassName={classNames(
                    accessoryStyles.accessoryOverlay,
                    overlayPositionClass
                  )}
                  hasShape={hasShape}
                  onClick={onShapeClick}
                />
              ) : null;
            return (
              <>
                <div className={classNames(sliceClass, accessoryStyles.accessoryOverlayHost)}>
                  <CellMarker
                    shape={shape}
                    shapeColor={shapeColor}
                    isShapesMode={isShapesMode}
                    cellIndex={cellIndex}
                    numberClassName={innerNumberClass}
                    iconClassName={innerIconClass}
                  />
                  {sliceOverlay}
                </div>
                {/* Mobile-only chip (hidden on desktop) — shared
                    `smartBlockMobileChip` class with VERTICAL_FUNNEL / STAIRCASE. */}
                <div
                  className={classNames(
                    styles.smartBlockMobileChip,
                    accessoryStyles.accessoryOverlayHost
                  )}
                >
                  {defaultMarker}
                  {overlay}
                </div>
              </>
            );
          }
          case 'CIRCLE': {
            return (
              <div className={accessoryStyles.bulletInline} data-circle-bullet>
                <div
                  className={classNames(styles.circleBadge, accessoryStyles.accessoryOverlayHost)}
                >
                  <CellMarker
                    shape={shape}
                    shapeColor={shapeColor}
                    isShapesMode={isShapesMode}
                    cellIndex={cellIndex}
                    iconClassName={styles.circleBadgeIcon}
                  />
                  {overlay}
                </div>
              </div>
            );
          }
          case 'STAIRCASE': {
            return (
              <>
                <div
                  className={classNames(styles.staircaseBar, accessoryStyles.accessoryOverlayHost)}
                >
                  <CellMarker
                    shape={shape}
                    shapeColor={shapeColor}
                    isShapesMode={isShapesMode}
                    cellIndex={cellIndex}
                    numberClassName={styles.staircaseInnerNumber}
                    iconClassName={styles.staircaseInnerIcon}
                  />
                  {overlay}
                </div>
                <div
                  className={classNames(
                    styles.smartBlockMobileChip,
                    accessoryStyles.accessoryOverlayHost
                  )}
                >
                  {defaultMarker}
                  {overlay}
                </div>
              </>
            );
          }
          default:
            return null;
        }
      })()}

      {contentSlot({
        className: styles.smartBlockCellContent,
        'data-smart-block-content': '',
        style: contentStyle.fontSize ? { fontSize: contentStyle.fontSize } : undefined,
        ...(contentStyle.headingLevel
          ? { 'data-heading-level': `header${HEADER_NAMES[contentStyle.headingLevel - 1]}` }
          : {}),
      })}

      {overlayChildren}
    </div>
  );
};
